import{_ as a,o,c as t,a5 as r}from"./chunks/framework.DOB-AMqW.js";const f=JSON.parse('{"title":"Flowra Data Collection","description":"Standalone data-collection disclosure for the Flowra application.","frontmatter":{"title":"Flowra Data Collection","description":"Standalone data-collection disclosure for the Flowra application.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-collection/flowra.md","filePath":"data-collection/flowra.md"}'),i={name:"data-collection/flowra.md"};function n(s,e,d,l,c,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="flowra-data-collection" tabindex="-1">Flowra Data Collection <a class="header-anchor" href="#flowra-data-collection" aria-label="Permalink to &quot;Flowra Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> August 19, 2026</p><h2 id="data-stored-locally" tabindex="-1">Data stored locally <a class="header-anchor" href="#data-stored-locally" aria-label="Permalink to &quot;Data stored locally&quot;">​</a></h2><p>Flowra may store profile and optional age information, menstrual and first-period details, reproductive life stage, period dates, daily flow, products, symptoms, moods, private notes, local predictions, reminder settings, and security and appearance preferences. This information is stored on the user&#39;s device and is not sent to the developer.</p><p>Android uses SQLite in private app storage. The database is not encrypted at the database level, and the optional app PIN does not encrypt it. Flowra disables Android cloud and device-transfer backup for its private app data.</p><p>The browser version encrypts records with AES-GCM before storing them in IndexedDB. Its non-exportable encryption key is stored in the same browser origin.</p><h2 id="data-collected-by-the-developer" tabindex="-1">Data collected by the developer <a class="header-anchor" href="#data-collected-by-the-developer" aria-label="Permalink to &quot;Data collected by the developer&quot;">​</a></h2><p>Flowra has no account, advertising, analytics, crash reporting, tracking, developer API, remote prediction service, or cloud sync. The developer does not collect profiles, menstrual records, symptoms, moods, notes, predictions, device identifiers, or app activity.</p><p>If you email support, the developer receives only the information you choose to include.</p><h2 id="optional-notifications-and-biometrics" tabindex="-1">Optional notifications and biometrics <a class="header-anchor" href="#optional-notifications-and-biometrics" aria-label="Permalink to &quot;Optional notifications and biometrics&quot;">​</a></h2><p>Android notification permission is requested only when local reminders are enabled. Notifications are scheduled on the device. Non-private notification wording may contain a profile name and estimated timing.</p><p>Optional biometric unlock uses Android&#39;s biometric prompt and Keystore. Flowra stores an encrypted PIN credential locally for that feature but does not access or receive biometric templates.</p><h2 id="user-created-files" tabindex="-1">User-created files <a class="header-anchor" href="#user-created-files" aria-label="Permalink to &quot;User-created files&quot;">​</a></h2><p>CSV exports and printable/PDF reports may contain period history and are not automatically encrypted. Password-protected <code>.flowra</code> backups contain local app records encrypted with AES-GCM. These files are created only at the user&#39;s request and are saved or shared under the user&#39;s control; they are not uploaded to the developer.</p><h2 id="browser-hosting-data" tabindex="-1">Browser hosting data <a class="header-anchor" href="#browser-hosting-data" aria-label="Permalink to &quot;Browser hosting data&quot;">​</a></h2><p>When the browser version is opened, its hosting provider may process standard connection data needed to deliver web files, such as IP address, user agent, request time, and requested path. This does not give the developer access to the encrypted health records stored by Flowra in IndexedDB.</p><h2 id="android-permissions" tabindex="-1">Android permissions <a class="header-anchor" href="#android-permissions" aria-label="Permalink to &quot;Android permissions&quot;">​</a></h2><p>The reviewed Android source declares notification and biometric/fingerprint compatibility permissions. It does not request camera, microphone, location, contacts, phone, call-log, SMS, calendar, or advertising-identifier access.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions can be sent to <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',20)])])}const m=a(i,[["render",n]]);export{f as __pageData,m as default};
